"""Render the llm-d-benchmark experiment file for the async-multitenant nightly.

The experiment is a sequence of treatment groups (llm-d-benchmark
`experiments/*.yaml` format, see llmdbenchmark/experiment/README.md):

    async_only                 [async]
    baseline_<L>               [realtime at k_L]        for each level L
    mixed_<L>                  [realtime at k_L, async] for each level L

Members of a group run concurrently against the same endpoint; groups run in
order. Per-treatment keys other than ``name``/``profile`` are dotted-path
overrides applied to the rendered inference-perf profile.

Only the standard library is used so the module can be unit-tested and run on
a bare GitHub runner.
"""
from __future__ import annotations

import math
from dataclasses import dataclass

REALTIME_PROFILE = "guide_async-multitenant_1.yaml"
ASYNC_PROFILE = "guide_async-multitenant_2.yaml"
DEFAULT_LEVELS = (20, 80, 90, 100)


@dataclass(frozen=True)
class ExperimentParams:
    """Knobs the orchestrator resolves from env before rendering."""
    capacity: int                  # C = maxConcurrency x ready replicas
    levels: tuple[int, ...] = DEFAULT_LEVELS
    realtime_seconds: float = 80.0  # target measured length of a realtime stage
    service_seconds: float = 2.0    # expected per-request service time
    async_rate: float = 10.0        # open-loop arrivals per second (>> pool throughput)
    # Must outlast the realtime member even when the two pods start minutes
    # apart (node provisioning, image pull); run.py derives it from
    # realtime_seconds plus a start-skew margin.
    async_duration: int = 180       # seconds of async arrivals
    async_timeout: int = 20         # client timeout that cancels undispatched work (~4x service time)
    realtime_timeout: int = 120
    realtime_num_requests: int | None = None  # override (dry runs)
    include_async_only: bool = True  # False when re-running only some levels


def concurrency_for_level(level: int, capacity: int) -> int:
    """Closed-loop realtime concurrency for a saturation level in percent."""
    if capacity <= 0:
        raise ValueError("capacity must be positive")
    if not 0 < level <= 100:
        raise ValueError(f"level must be in (0, 100], got {level}")
    return max(1, round(level / 100.0 * capacity))


def num_requests_for(k: int, params: ExperimentParams) -> int:
    """Requests a closed-loop stage needs to last ~realtime_seconds."""
    if params.realtime_num_requests is not None:
        return max(1, params.realtime_num_requests)
    return max(k, math.ceil(k * params.realtime_seconds / params.service_seconds))


def treatment_names(levels=DEFAULT_LEVELS, include_async_only: bool = True) -> list[str]:
    """Every treatment the rendered experiment produces, in run order."""
    names = ["async_only"] if include_async_only else []
    for level in levels:
        names += [f"baseline_{level}", f"mixed_{level}_async", f"mixed_{level}_rt"]
    return names


def _fmt(value) -> str:
    if isinstance(value, float):
        return repr(value)
    return str(value)


def _async_member(name: str, params: ExperimentParams) -> list[str]:
    return [
        f"      - name: {name}",
        f"        profile: {ASYNC_PROFILE}",
        f"        load.stages.0.rate: {_fmt(params.async_rate)}",
        f"        load.stages.0.duration: {params.async_duration}",
        f"        load.request_timeout: {params.async_timeout}",
    ]


def _realtime_member(name: str, k: int, params: ExperimentParams) -> list[str]:
    return [
        f"      - name: {name}",
        f"        profile: {REALTIME_PROFILE}",
        f"        load.stages.0.concurrency_level: {k}",
        f"        load.stages.0.num_requests: {num_requests_for(k, params)}",
        f"        load.request_timeout: {params.realtime_timeout}",
    ]


def render_experiment(params: ExperimentParams) -> str:
    """Return the experiment YAML as text (no PyYAML dependency).

    In each mixed group the async member is listed first so its pod is
    deployed first; together with an async stage that outlasts the realtime
    stage by a start-skew margin, the realtime member runs inside the async
    backlog even when the two pods start minutes apart.
    """
    lines = [
        "# Generated by .github/scripts/e2e/async-multitenant/run.py; do not edit.",
        "name: async-multitenant-isolation",
        "# Run-only mode has no cache to reset; contention is the result, not a defect.",
        "reset_caches: false",
        "# No per-treatment retry: a retried group member would run alone. run.py",
        "# re-runs whole levels instead when a comparison comes back invalid.",
        "treatment_max_attempts: 1",
        "treatment_stop_on_error: false",
        "max_parallel_treatments: 2",
        "",
        "groups:",
    ]
    if params.include_async_only:
        lines += ["  - name: async_only", "    treatments:"]
        lines += _async_member("async_only", params)
    for i, level in enumerate(params.levels):
        k = concurrency_for_level(level, params.capacity)
        if i or params.include_async_only:
            lines.append("")
        lines += [f"  - name: baseline_{level}", "    treatments:"]
        lines += _realtime_member(f"baseline_{level}", k, params)
        lines += ["", f"  - name: mixed_{level}", "    treatments:"]
        lines += _async_member(f"mixed_{level}_async", params)
        lines += _realtime_member(f"mixed_{level}_rt", k, params)
    return "\n".join(lines) + "\n"
